import{_ as o,c as t,a2 as l,o as r}from"./chunks/framework.Bzjhwp8w.js";const a="/dllm/assets/746bd1f12de464e7b6b3f5fc48a5fa09.D9j6dBYd.gif",u=JSON.parse('{"title":"整合 Google Cloud Vertex AI 与 Langflow","description":"整合 Google Cloud Vertex AI 与 Langflow","frontmatter":{"title":"整合 Google Cloud Vertex AI 与 Langflow","description":"整合 Google Cloud Vertex AI 与 Langflow","layout":"doc"},"headers":[],"relativePath":"langflow/integrations-setup-google-cloud-vertex-ai-langflow.md","filePath":"langflow/integrations-setup-google-cloud-vertex-ai-langflow.md"}'),n={name:"langflow/integrations-setup-google-cloud-vertex-ai-langflow.md"};function g(s,e,i,d,c,p){return r(),t("div",null,e[0]||(e[0]=[l('<h1 id="整合-google-cloud-vertex-ai-与-langflow" tabindex="-1">整合 Google Cloud Vertex AI 与 Langflow <a class="header-anchor" href="#整合-google-cloud-vertex-ai-与-langflow" aria-label="Permalink to &quot;整合 Google Cloud Vertex AI 与 Langflow&quot;">​</a></h1><p>Langflow 集成了 <a href="https://console.cloud.google.com/marketplace/product/google/aiplatform.googleapis.com" target="_blank" rel="noreferrer">Google Vertex AI API</a> 以进行 <a href="/dllm/components-embedding-models.html#vertexai-embeddings">Vertex AI embeddings 模型</a> 和 <a href="/dllm/components-models.html#vertexai">Vertex AI</a> 组件的身份验证。</p><p>了解如何在 Google Cloud 中创建服务账户 JSON 以验证 Langflow 的 Vertex AI 组件。</p><h2 id="创建具有-vertex-ai-访问权限的服务账户" tabindex="-1">创建具有 Vertex AI 访问权限的服务账户 <a class="header-anchor" href="#创建具有-vertex-ai-访问权限的服务账户" aria-label="Permalink to &quot;创建具有 Vertex AI 访问权限的服务账户&quot;">​</a></h2><ol><li><p>选择并启用您的 Google Cloud 项目。 有关更多信息，请参阅<a href="https://developers.google.com/workspace/guides/create-project" target="_blank" rel="noreferrer">创建 Google Cloud 项目</a>。</p></li><li><p>在您的 Google Cloud 项目中创建一个服务账户。 有关更多信息，请参阅<a href="https://developers.google.com/workspace/guides/create-credentials#service-account" target="_blank" rel="noreferrer">创建服务账户</a>。</p></li><li><p>为您的新账户分配 <strong>Vertex AI Service Agent</strong> 角色。 此角色允许 Langflow 访问 Vertex AI 资源。 有关更多信息，请参阅<a href="https://cloud.google.com/vertex-ai/docs/general/access-control" target="_blank" rel="noreferrer">使用 IAM 进行 Vertex AI 访问控制</a>。</p></li><li><p>要为服务账户生成新的 JSON 密钥，请导航到您的服务账户。</p></li><li><p>点击 <strong>Add Key</strong>，然后点击 <strong>Create new key</strong>。</p></li><li><p>在 <strong>Key type</strong> 下选择 <strong>JSON</strong>，然后点击 <strong>Create</strong>。 一个 JSON 私钥文件将被下载。 现在您已有一个服务账户和一个 JSON 私钥，您需要在 Langflow 组件中配置凭证。</p></li></ol><h2 id="在-langflow-组件中配置凭据" tabindex="-1">在 Langflow 组件中配置凭据 <a class="header-anchor" href="#在-langflow-组件中配置凭据" aria-label="Permalink to &quot;在 Langflow 组件中配置凭据&quot;">​</a></h2><p>在配置好您的服务账户并创建凭据 JSON 文件后，按照以下步骤对 Langflow 应用程序进行身份验证。</p><ol><li>在 Langflow 中创建一个新项目。</li><li>从组件侧边栏中，将 <strong>Vertex AI</strong> 或 <strong>Vertex AI Embeddings</strong> 组件拖放到您的工作区。</li><li>在 Vertex AI 组件的 <strong>Credentials（凭据）</strong> 字段中，添加服务账户的 JSON 文件。</li><li>确认组件可以访问 Vertex AI 资源。将 <strong>Chat input（聊天输入）</strong> 和 <strong>Chat output（聊天输出）</strong> 组件连接到 Vertex AI 组件。成功的聊天确认组件已能访问 Vertex AI 资源。</li></ol><p><img src="'+a+'" alt="Configure Vertex AI Credentials in Langflow"></p>',9)]))}const x=o(n,[["render",g]]);export{u as __pageData,x as default};
